export function listTasks(query: TaskQuery, tasks: readonly Task[] = TASKS): Page<Task> {
  // Validate and parse filters
  const allowedStatuses: readonly Status[] = ["todo", "doing", "done"];
  let statusFilter: readonly Status[] | null = null;
  if (query.status !== undefined) {
    const parts = query.status.split(",");
    const statuses: Status[] = [];
    for (const part of parts) {
      const s = part.trim();
      if (!s) {
        throw new ValidationError("status", "invalid status");
      }
      if (!allowedStatuses.includes(s as Status)) {
        throw new ValidationError("status", "invalid status");
      }
      statuses.push(s as Status);
    }
    statusFilter = statuses;
  }

  let assigneeFilter: string | null | undefined = undefined;
  if (query.assignee !== undefined) {
    if (query.assignee === "none") {
      assigneeFilter = null;
    } else {
      assigneeFilter = query.assignee;
    }
  }

  let tagFilter: string | undefined = undefined;
  if (query.tag !== undefined) {
    tagFilter = query.tag;
  }

  let qFilter: string | undefined = undefined;
  if (query.q !== undefined) {
    const trimmed = query.q.trim();
    if (trimmed.length > 0) {
      qFilter = trimmed.toLowerCase();
    }
  }

  // Sorting
  let sortField: "dueDate" | "priority" | "title" = "priority";
  let sortDir: "asc" | "desc" = "desc";
  if (query.sort !== undefined) {
    const parts = query.sort.split(":");
    if (parts.length !== 2) {
      throw new ValidationError("sort", "invalid sort");
    }
    const [field, dir] = parts;
